#include <chrono>
#include <format>
#include <sstream>
#include <string>
#include <cassert>
#include <iostream>

int main() {
    using namespace std::chrono;
    year_month_weekday date{year{2024} / March / Friday[3]};
    assert(date.ok());
    std::ostringstream text;
    text << date;
    assert(!text.str().empty());
    auto formatted = std::format("{}", date);
    assert(!formatted.empty());
    std::cout << "Checks passed\n";
}
